<?php /** @var array $x @var string $tab */ $cid = (int)$x['c']['id']; $tabs = ['overview' => ['icaap.tab_overview', 'icaap/' . $cid], 'capital' => ['icaap.tab_capital', 'icaap/' . $cid . '/capital'], 'risks' => ['icaap.tab_risks', 'icaap/' . $cid . '/risks'],
  'stress' => ['icaap.tab_stress', 'icaap/' . $cid . '/stress'], 'log' => ['icaap.tab_log', 'icaap/' . $cid . '/log'], 'report' => ['icaap.tab_report', 'icaap/' . $cid . '/report']];
$locked = in_array($x['c']['status'], ['submitted', 'closed'], true); ?>
<div class="page-head"><div><h1><?= icon('scale') ?> <?= e(t('icaap.title')) ?> <?= (int)$x['c']['year'] ?></h1><p class="sub"><?= e(t('icaap.data_date')) ?>: <?= e(fdate($x['c']['data_date'])) ?> · <span class="badge"><?= e(t('enum.icst.' . $x['c']['status'])) ?></span><?= $x['c']['regulatory_deadline'] ? ' · ' . e(t('icaap.deadline')) . ': ' . e(fdate($x['c']['regulatory_deadline'])) : '' ?></p></div>
