<nav class="pill-tabs" aria-label="ICAAP"><?php foreach ($tabs as $k => [$lbl, $href]): ?><a href="<?= e(url($href)) ?>"<?= $k === $tab ? ' aria-current="page" class="active"' : '' ?>><?= e(t($lbl)) ?></a><?php endforeach; ?></nav>
